@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<BlockGridItem<RichTextBlock>>
@{
    var model = new RichTextModel
    {
        Heading = Model.Content.Heading,
        Body = Model.Content.Body
    };
}
@await Component.InvokeAsync("RichText", new { model })

@model Umbraco.Bench.Umbraco.Models.Blocks.HeroModel
<section class="overflow-hidden bg-slate-950 text-white">
    <div class="mx-auto grid max-w-6xl gap-10 px-6 py-16 lg:grid-cols-2 lg:items-center lg:px-8 lg:py-24">
        <div>
            <p class="mb-4 text-sm font-semibold uppercase tracking-[0.2em] text-cyan-300">MCP Field Notes</p>
            <h1 class="max-w-2xl text-4xl font-bold tracking-tight sm:text-6xl">@Model.Heading</h1>
            @if (!string.IsNullOrWhiteSpace(Model.Summary))
            {
                <p class="mt-6 max-w-xl text-lg leading-8 text-slate-300">@Model.Summary</p>
            }
        </div>
        @if (!string.IsNullOrWhiteSpace(Model.ImageUrl))
        {
            <img class="h-72 w-full rounded-2xl object-cover shadow-2xl lg:h-96" src="@Model.ImageUrl" alt="@Model.ImageAlt" />
        }
    </div>
</section>

@using Umbraco.Bench.Umbraco.Models
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<BlogPost>
@{
    Layout = null;
    var blog = Model.Parent<BlogFrontPage>();
}
<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>@Model.Name</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-slate-50 text-slate-950 antialiased">
    <nav class="mx-auto max-w-6xl px-6 py-5 lg:px-8">
        <a class="text-sm font-semibold text-cyan-700 hover:text-cyan-900" href="@(blog?.Url() ?? "/")">&larr; All field notes</a>
    </nav>
    @await Html.GetBlockGridHtmlAsync(Model, "blocks")
</body>
</html>

@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Bench.Umbraco.Models.Blocks
@using Umbraco.Cms.Core.Models.Blocks
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<BlockGridItem<HeroBlock>>
@{
    var model = new HeroModel
    {
        Heading = Model.Content.Heading ?? string.Empty,
        Summary = Model.Content.Summary,
        ImageUrl = Model.Content.Image?.GetCropUrl(width: 1600),
        ImageAlt = Model.Content.Image?.Name
    };
}
@await Component.InvokeAsync("Hero", new { model })

using Microsoft.AspNetCore.Mvc;
using Umbraco.Bench.Umbraco.Models.Blocks;

namespace Umbraco.Bench.Umbraco.ViewComponents;

public sealed class RichTextViewComponent : ViewComponent
{
    public IViewComponentResult Invoke(RichTextModel model) => View(model);
}

